 public void CopySharedSettingsTo(MasterFx n){n.ReverbMode=ReverbMode;n.DelayMode=DelayMode;n.Routing=Routing;n.SerialOrder=SerialOrder;n.GrainMix=GrainMix;n.HallTone=HallTone;n.Size=Size;n.Time=Time;n.Feedback=Feedback;n.GrainSize=GrainSize;n.GrainPitch=GrainPitch;n.Spray=Spray;n.DelaySync=DelaySync;n.Division=Division;n.Feel=Feel;n.Tempo=Tempo;n.Density=Density;n.Position=Position;n.Freeze=Freeze;n.GrainReverse=GrainReverse;n.GrainMode=GrainMode;n.CloudFeedback=CloudFeedback;n.Cloudy=Cloudy;n.CloudWindow=CloudWindow;n.Texture=Texture;n.Spread=Spread;n.CloudLoFi=CloudLoFi;}
 float Random(){random^=random<<13;random^=random>>17;random^=random<<5;return (random&0x7fffffff)/2147483648f;}
 internal static float Read(float[] data,double position){position=(position%data.Length+data.Length)%data.Length;int i=(int)position,j=(i+1)%data.Length;double f=position-i;return (float)(data[i]*(1-f)+data[j]*f);}
 public volatile int SerialOrder;int activeRoute=1,activeOrder;float routeGate=1;readonly float[] effectWetL=new float[3],effectWetR=new float[3];
 void SmoothRoute(){int route=Math.Max(0,Math.Min(2,Routing)),order=Math.Max(0,Math.Min(5,SerialOrder));if(route!=activeRoute||order!=activeOrder){routeGate+=(0-routeGate)*.004f;if(routeGate<.0001f){activeRoute=route;activeOrder=order;routeGate=0;}}else{routeGate+=(1-routeGate)*.004f;if(routeGate>.9999f)routeGate=1;}}
 public void Process(float l,float r,out float wetL,out float wetR){ResetRamp();SmoothRoute();rs+=(Reverb-rs)*.003f;ds+=(Delay-ds)*.003f;gs+=(Grain-gs)*.003f;if(Grain==0&&gs<.00001f)gs=0;time+=(DelaySeconds-time)*.0005;
 if(activeRoute==1){float stageL=l,stageR=r;var order=FxOrder.Items(activeOrder);for(int i=0;i<3;i++){int id=order[i];Node(id,stageL,stageR);stageL+=effectWetL[id];stageR+=effectWetR[id];}}
 else if(activeRoute==2){Node(2,l,r);float stageL=l+effectWetL[2],stageR=r+effectWetR[2];Node(1,stageL,stageR);Node(0,stageL,stageR);}else{Node(2,l,r);Node(1,l,r);Node(0,l,r);}
 wetL=(effectWetL[0]+effectWetL[1]+effectWetL[2])*resetGate*routeGate;wetR=(effectWetR[0]+effectWetR[1]+effectWetR[2])*resetGate*routeGate;}
 void Node(int kind,float l,float r){if(kind==2)GrainNode(l,r);else if(kind==1)DelayNode(l,r);else ReverbNode(l,r);}
 void GrainNode(float l,float r){ if(!Freeze){historyL[historyAt]=l;historyR[historyAt]=r;}if(--untilGrain<=0&&gs>.00001f){int length=(int)(Math.Max(.01f,Math.Min(.4f,GrainSize))*48000);untilGrain=Math.Max(1,(int)(length/Math.Max(1,Math.Min(12,Density))));foreach(var v in voices)if(v.Age>=v.Length){v.Age=0;v.Length=length;v.Rate=Math.Pow(2,Math.Max(-12,Math.Min(12,GrainPitch))/12.0);v.Band=Math.Max(8,Math.Min(32,(int)Math.Ceiling(v.Rate*16)));v.Position=historyAt-length*Math.Max(1,v.Rate)-64-Math.Max(0,Math.Min(1.5f,Position))*48000-Random()*Math.Max(0,Math.Min(1,Spray))*24000;if(GrainReverse){v.Position+=length*v.Rate;v.Rate=-v.Rate;}break;}}
 float gl=0,gr=0,weight=0;foreach(var v in voices)if(v.Age<v.Length){float w=GrainWindow[(int)((long)v.Age*2047/v.Length)];gl+=GrainRead(historyL,v.Position,v.Band)*w;gr+=GrainRead(historyR,v.Position,v.Band)*w;weight+=w;v.Age++;v.Position+=v.Rate;}if(!Freeze)historyAt=(historyAt+1)%historyL.Length;float norm=1/Math.Max(1,weight);float cl=0,cr=0;cloudBlend+=((GrainMode==0?0:1)-cloudBlend)*.003f;if(GrainMode!=0||cloudBlend>.00001f)cloud.Process(l,r,this,out cl,out cr);gl=gl*norm*(1-cloudBlend)+cl*cloudBlend;gr=gr*norm*(1-cloudBlend)+cr*cloudBlend;mixSmooth+=(Math.Max(0,Math.Min(1,GrainMix))-mixSmooth)*.003f;if(Math.Abs(GrainMix-mixSmooth)<.00005f)mixSmooth=Math.Max(0,Math.Min(1,GrainMix));float amount=gs<.00005f?0:gs>.99995f?1:gs;float dry=1+(Math.Min(1,2*(1-mixSmooth))-1)*amount,wet=Math.Min(1,2*mixSmooth);effectWetL[2]=gl*gs*wet+l*(dry-1);effectWetR[2]=gr*gs*wet+r*(dry-1);}
 void DelayNode(float l,float r){ float dl=Read(delayL,delayAt-time*48000),dr=Read(delayR,delayAt-time*48000),fb=feedbackSmooth;feedbackSmooth+=(Math.Max(0,Math.Min(.85f,Feedback))-feedbackSmooth)*.003f;pingBlend+=((DelayMode==1?1:0)-pingBlend)*.003f;potsBlend+=((DelayMode==2?1:0)-potsBlend)*.003f;float mono=(l+r)*.5f;delayL[delayAt]=(l+(mono-l)*pingBlend)*ds+(dl+(dr-dl)*pingBlend)*fb;delayR[delayAt]=r*(1-pingBlend)*ds+(dr+(dl-dr)*pingBlend)*fb;delayAt=(delayAt+1)%delayL.Length;if(DelayMode==2||potsBlend>.00001f){float pot=pots.process((l+r)*.5f*ds,DelaySeconds,fb);dl+=(pot-dl)*potsBlend;dr+=(pot-dr)*potsBlend;potsActive=true;}else if(potsActive){pots.clear();potsActive=false;}
effectWetL[1]=dl*.5f;effectWetR[1]=dr*.5f;}
 void ReverbNode(float l,float r){ float reL,reR,rl=0,rr=0;roomBlend+=((ReverbMode==1?1:0)-roomBlend)*.003f;hall.Tone=room.Tone=HallTone;float hl=l*rs,hr=r*rs;hall.Process(hl,hr,Size,out reL,out reR);if(ReverbMode==1||roomBlend>.00001f){room.Process(hl,hr,Size,out rl,out rr);roomActive=true;}else if(roomActive){room.Clear();roomActive=false;}reL+=(rl-reL)*roomBlend;reR+=(rr-reR)*roomBlend;effectWetL[0]=reL;effectWetR[0]=reR;}
 internal void SnapRouting(){activeRoute=Math.Max(0,Math.Min(2,Routing));activeOrder=Math.Max(0,Math.Min(5,SerialOrder));routeGate=1;}
 public void ResetDefaults(){ReverbMode=DelayMode=0;Routing=1;SerialOrder=0;Reverb=Delay=Grain=Filter=GrainPitch=0;Size=HallTone=GrainMix=.5f;Time=.375f;Feedback=.35f;GrainSize=.09f;Spray=.3f;GrainMode=0;CloudFeedback=.45f;Cloudy=Texture=.65f;CloudWindow=.25f;Spread=.75f;CloudLoFi=Freeze=GrainReverse=false;DelaySync=true;Division=2;Feel=1;Density=4;Position=.15f;resetRequested=true;}
 void ResetRamp(){if(resetRequested){resetRequested=false;resetPhase=1;}if(resetPhase==1){resetGate+=(0-resetGate)*.003f;if(resetGate<.0001f){Clear();resetPhase=2;}}else if(resetPhase==2){resetGate+=(1-resetGate)*.003f;if(resetGate>.9999f){resetGate=1;resetPhase=0;}}}
 public void Clear(){masterFilter.Clear();cloud.Clear();cloudBlend=0;hall.Clear();room.Clear();pots.clear();potsActive=roomActive=false;Array.Clear(delayL,0,delayL.Length);Array.Clear(delayR,0,delayR.Length);Array.Clear(historyL,0,historyL.Length);Array.Clear(historyR,0,historyR.Length);foreach(var v in voices)v.Age=v.Length;}
 public double ReverbSeconds{get{return HallFx.Seconds(Size,ReverbMode==1);}}
 public string TabLabel(int tab){return tab==0?(ReverbMode==1?"ROOM":"HALL"):tab==1?(DelayMode==1?"Ping-Pong":DelayMode==2?"POTS":"DELAY"):new[]{"GRANULAR","CLOUDS","CLOUD DLY"}[GrainMode]+(Freeze?" *":"");}
 public void CycleType(int tab){if(tab==0)ReverbMode=(ReverbMode+1)%2;else if(tab==1)DelayMode=(DelayMode+1)%3;else GrainMode=(GrainMode+1)%3;}
 public double DelaySeconds{get{return DelaySync?60.0/Math.Max(20,Math.Min(300,Tempo))*BeatValues[Math.Max(0,Math.Min(5,Division))]*(Feel==1?1.5:Feel==2?2.0/3:1):Math.Max(.04,Math.Min(1.5,Time));}}
 public string DelayLabel{get{return DelaySync?new string[]{"1/32","1/16","1/8","1/4","1/2","1/1"}[Math.Max(0,Math.Min(5,Division))]+(Feel==1?" D":Feel==2?" T":""): (Time*1000).ToString("0")+"ms";}}
 static readonly double[] BeatValues={.125,.25,.5,1,2,4};
 internal static readonly float[] GrainWindow=MakeWindow();static readonly float[][] Kernels=MakeKernels();
 static float[] MakeWindow(){var w=new float[2048];for(int i=0;i<w.Length;i++)w[i]=(float)(.5-.5*Math.Cos(2*Math.PI*i/2047));return w;}
 static float[][] MakeKernels(){var table=new float[33*256][];for(int b=8;b<=32;b++)for(int phase=0;phase<256;phase++){var k=new float[16];double sum=0,cut=Math.Min(.95,15.2/b);for(int t=0;t<16;t++){double x=t-7-phase/256.0,z=Math.PI*x*cut;double q=(Math.Abs(z)<1e-9?cut:Math.Sin(z)/(Math.PI*x))*(.5+.5*Math.Cos(Math.PI*x/8));k[t]=(float)q;sum+=q;}for(int t=0;t<16;t++)k[t]/=(float)sum;table[b*256+phase]=k;}return table;}
 internal static float GrainRead(float[] data,double position,int band){position=(position%data.Length+data.Length)%data.Length;int at=(int)position;var k=Kernels[band*256+Math.Min(255,(int)((position-at)*256))];float value=0;for(int t=0;t<16;t++)value+=data[(at+t-7+data.Length)%data.Length]*k[t];return value;}

}
